param(
 [Parameter(Mandatory=$true)][string]$OwnerPath,
 [Parameter(Mandatory=$true)][string]$IoctlPath,
 [Parameter(Mandatory=$true)][string]$LoaderPath,
 [Parameter(Mandatory=$true)][string]$ServicePath,
 [Parameter(Mandatory=$true)][string]$PublicHeaderPath,
 [Parameter(Mandatory=$true)][string]$PublicSourcePath,
 [Parameter(Mandatory=$true)][string]$EptHeaderPath,
 [Parameter(Mandatory=$true)][string]$TestPath)
$ErrorActionPreference='Stop'
function A([bool]$x,[string]$m){if(-not$x){throw $m}}
function O([string]$t,[string[]]$v,[string]$n){$p=-1;foreach($x in $v){$q=$t.IndexOf($x,$p+1);A ($q-gt$p) "$n $x";$p=$q}}
function S([string]$t,[string]$a,[string]$b){$x=$t.IndexOf($a);$y=$t.IndexOf($b,$x+1);A ($x-ge0-and$y-gt$x) "section $a";$t.Substring($x,$y-$x)}
function V([string]$o,[string]$i,[string]$l,[string]$s,[string]$h,[string]$p,[string]$eh,[string]$t){
 $x=S $o 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerAttach(' 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerStart(';O $x @('OwnerEnter(o)','VMX_PERSISTENT_DRIVER_OWNER_ATTACHING','VmxPersistentRuntimeInitialize','VMX_PERSISTENT_DRIVER_OWNER_ATTACHED','OwnerLeave(o)') 'owner attach'
 $x=S $o 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerStart(' 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerStop(';O $x @('OwnerEnter(o)','VmxPersistentRuntimeStart','OwnerLeave(o)') 'owner start'
 $x=S $o 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerStop(' 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerDetach(';O $x @('OwnerEnter(o)','VmxPersistentRuntimeStop','OwnerLeave(o)') 'owner stop'
 $x=S $o 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerDetach(' 'VMX_PERSISTENT_STATUS VmxPersistentDriverOwnerQueryOccupied(';O $x @('OwnerEnter(o)','VMX_PERSISTENT_DRIVER_OWNER_TEARDOWN_PENDING','VmxPersistentRuntimeDestroy','VMX_PERSISTENT_DRIVER_OWNER_DETACHED','OwnerLeave(o)') 'owner detach'
 $x=S $i 'IoctlDispatchLoad(' 'IoctlDispatchUnload(';O $x @('VmxPersistentRuntimeConfigBuild','VmxEptPersistentDeviceStart','ERR_PERSISTENT_START_FAILED','ERR_PERSISTENT_LIFECYCLE_FAILED','ERR_PERSISTENT_ROLLBACK_FAILED') 'ioctl load'
 $x=S $i 'IoctlDispatchUnload(' 'IoctlDispatchHook(';O $x @('VmxPersistentDriverOwnerQueryPhase','ERR_DRIVER_NOT_LOADED','VmxEptPersistentDeviceTeardown','ERR_SUCCESS') 'ioctl unload'
 $x=S $i 'IoctlDispatchPersistentStatusQuery(' 'IOCTL Dispatch: EPT_STATUS_QUERY';O $x @('RtlZeroMemory(output_buffer, output_length)','VmxPersistentDriverOwnerAcquireStatusSnapshot','STATUS_BUFFER_TOO_SMALL','RtlCopyMemory(output_buffer, snapshot.Buffer, snapshot.Size)','VmxPersistentDriverOwnerReleaseStatusSnapshot','WdfRequestCompleteWithInformation') 'runtime status'
 $x=S $i 'IoctlDispatchEptStatusQuery(' 'Main IOCTL Dispatch';O $x @('RtlZeroMemory(output_buffer, output_length)','IoctlValidateEptStatusQueryRequest','STATUS_BUFFER_TOO_SMALL','VmxEptPersistentDeviceStatusProject','HYPERVISOR_EPT_STATUS_RESPONSE_SIZE','WdfRequestCompleteWithInformation') 'EPT status'
 $x=S $l 'static int CmdLoadInternal(' 'static int CmdLoad(void)';O $x @('IOCTL_HYPERVISOR_LOAD','QueryPersistentStatus','QueryEptStatus','LoaderDecideLoadVerification','LoaderEptStatusProvesReady','IOCTL_HYPERVISOR_UNLOAD','QueryPersistentDetachedStatus','QueryEptStatus','LoaderEptStatusProvesDetached','CleanupDriverServiceAfterDetachedProof') 'loader load'
 $x=S $l 'static int CmdUnload(void)' 'static int CmdHook';O $x @('IOCTL_HYPERVISOR_UNLOAD','QueryPersistentDetachedStatus','QueryEptStatus','LoaderDecideScmCleanup','LoaderEptStatusProvesDetached','CleanupDriverServiceAfterDetachedProof') 'loader unload'
 $x=S $l 'static BOOL CleanupDriverServiceAfterDetachedProof' 'static const char* ProbeStageName';O $x @('CloseHandle(g_device_handle)','StopDriverService','DeleteDriverService','WaitForDriverServiceAbsent') 'loader cleanup'
 $wh=S $h 'typedef struct _VMX_PERSISTENT_PUBLIC_STATUS_HEADER' 'typedef struct _VMX_PERSISTENT_PUBLIC_CONTEXT_RECORD';$wr=S $h 'typedef struct _VMX_PERSISTENT_PUBLIC_CONTEXT_RECORD' '#define VMX_PERSISTENT_PUBLIC_STATUS_HEADER_SIZE';A ($wh-notmatch '\*'-and$wr-notmatch '\*') 'runtime wire pointers forbidden'
 $er=S $eh 'typedef struct HYPERVISOR_EPT_STATUS_RESPONSE' '#ifdef __cplusplus';A ($er-notmatch '\*') 'EPT response pointers forbidden';foreach($z in @('HYPERVISOR_EPT_STATUS_RESPONSE_SIZE UINT32_C(128)','HYPERVISOR_EPT_STATUS_READY','HYPERVISOR_EPT_STATUS_DETACHED','HYPERVISOR_EPT_STATUS_FLAG_CLEANUP_REQUIRED')){A ($eh.Contains($z)) "EPT ABI $z"}
 foreach($z in @('query_valid && classification == LOADER_PERSISTENT_WIRE_LOADED','query_valid && classification == LOADER_EPT_WIRE_READY','query_valid && classification == LOADER_EPT_WIRE_DETACHED','!device_opened || status_proof != LOADER_PERSISTENT_STATUS_DETACHED')){A ($s.Contains($z)) "policy $z"}
 foreach($z in @('0x80002000','0x80002004','0x80002010','0x80002018','0x80002020','sizeof(HYPERVISOR_EPT_STATUS_RESPONSE)==128','canonical 0x807 LOADED','canonical 0x808 EPT READY','dual LOAD proof accepted','canonical 0x808 EPT DETACHED','dual detached proof accepted','EPT cleanup pending requires retry','EPT residual rejects LOAD proof','EPT residual rejects cleanup proof','EPT query failure rolls back','EPT ready wire immutable','EPT detached wire immutable')){A ($t.Contains($z)) "test $z"}
 foreach($z in @('required=0;if(out_size)memset(out,0,out_size)','memset(out,0,out_size)')){A ($p.Contains($z)) "encoder $z"}
}
$o=[IO.File]::ReadAllText((Resolve-Path $OwnerPath));$i=[IO.File]::ReadAllText((Resolve-Path $IoctlPath));$l=[IO.File]::ReadAllText((Resolve-Path $LoaderPath));$s=[IO.File]::ReadAllText((Resolve-Path $ServicePath));$h=[IO.File]::ReadAllText((Resolve-Path $PublicHeaderPath));$p=[IO.File]::ReadAllText((Resolve-Path $PublicSourcePath));$eh=[IO.File]::ReadAllText((Resolve-Path $EptHeaderPath));$t=[IO.File]::ReadAllText((Resolve-Path $TestPath));V $o $i $l $s $h $p $eh $t
$om=@($o.Replace('VmxPersistentRuntimeStart(&o->Runtime)','VMX_PERSISTENT_STATUS_OK'),$o.Replace('VmxPersistentRuntimeStop(&o->Runtime)','VMX_PERSISTENT_STATUS_OK'),$o.Replace('status=VmxPersistentRuntimeDestroy(&o->Runtime);','status=0;'));foreach($m in $om){A ($m-ne$o) 'vacuous owner mutation';$bad=$false;try{V $m $i $l $s $h $p $eh $t}catch{$bad=$true};A $bad 'accepted owner mutation'}
$im=@($i.Replace('start_status = VmxEptPersistentDeviceStart(device_context, &config);','start_status = VMX_EPT_PERSISTENT_DEVICE_START_OK;'),$i.Replace('teardown_status = VmxEptPersistentDeviceTeardown(device_context);','teardown_status = VMX_EPT_PERSISTENT_DEVICE_TEARDOWN_OK;'),$i.Replace('project_status = VmxEptPersistentDeviceStatusProject(','project_status = VMX_EPT_PERSISTENT_DEVICE_STATUS_OK; /*'));foreach($m in $im){A ($m-ne$i) 'vacuous ioctl mutation';$bad=$false;try{V $o $m $l $s $h $p $eh $t}catch{$bad=$true};A $bad 'accepted ioctl mutation'}
$lm=@($l.Replace('ept_query_valid = QueryEptStatus(&ept_classification);','ept_query_valid = TRUE;'),$l.Replace('LoaderEptStatusProvesReady(','LoaderEptStatusProvesDetached('),$l.Replace('detached_ept_query_valid = QueryEptStatus(','detached_ept_query_valid = TRUE; /*'),$l.Replace('CloseHandle(g_device_handle);','g_device_handle = INVALID_HANDLE_VALUE;'));foreach($m in $lm){A ($m-ne$l) 'vacuous loader mutation';$bad=$false;try{V $o $i $m $s $h $p $eh $t}catch{$bad=$true};A $bad 'accepted loader mutation'}
$sm=@($s.Replace('classification == LOADER_EPT_WIRE_READY','classification == LOADER_EPT_WIRE_RESIDUAL'),$s.Replace('classification == LOADER_EPT_WIRE_DETACHED','classification == LOADER_EPT_WIRE_RESIDUAL'),$s.Replace('!device_opened || status_proof != LOADER_PERSISTENT_STATUS_DETACHED','false'));foreach($m in $sm){A ($m-ne$s) 'vacuous policy mutation';$bad=$false;try{V $o $i $l $m $h $p $eh $t}catch{$bad=$true};A $bad 'accepted policy mutation'}
$hm=@($eh.Replace('uint32_t Version, Size, Classification, Flags;','void* Version; uint32_t Size, Classification, Flags;'));foreach($m in $hm){A ($m-ne$eh) 'vacuous EPT ABI mutation';$bad=$false;try{V $o $i $l $s $h $p $m $t}catch{$bad=$true};A $bad 'accepted EPT ABI mutation'}
'Verified pre-live Runtime+EPT LOAD/READY/UNLOAD/DETACHED/SCM integration, retries, pointer-free ABIs, and fail-closed proof order.'
